function AIWrite() {
  return (
    <div style={{ padding: "12px" }}>
      <h2>AI 독후감 생성</h2>

      <textarea
        placeholder="사진 찍은 글귀 / 느낌 입력"
        style={{ width: "100%", height: "150px" }}
      />

      <button style={{
        width: "100%",
        marginTop: "10px",
        padding: "10px"
      }}>
        AI로 독후감 생성
      </button>

      <div style={{ marginTop: "20px" }}>
        <h4>생성 결과</h4>
        <p>여기에 AI 독후감이 출력됩니다</p>
      </div>
    </div>
  );
}

export default AIWrite;
